--region private
---@param quest MidFestivalMainQuestLevelVo
function ActivityMidFestivalLeftTabCellNode:InitData(quest, isSelected)
    self.questVo = quest
    self.config.isSelected = isSelected
    self.config.isLock = quest.status == 2 -- 锁定
    self.config.isGet = quest.status == 0 -- 已通关
    self.config.isNew = quest.status == 1 -- 新解锁

    local type = self.questVo.type
    -- 纯剧情
    self._purePlot = checkNumber(type) == 1

    self:RefreshUI()
end

function ActivityMidFestivalLeftTabCellNode:RefreshUI()
    if isNull(self.questVo) then
        return
    end

    if not string.isEmpty(self.questVo.name) then
        CfUtils.FillText(self.TxtName, self.questVo.name)
    end


    self.ImgIcon.Status = self._purePlot and 1 or 2
    self.ImgIconSelect.Status = self._purePlot and 1 or 2
    CfUtils.SetActive(self.ImgIcon, not self.config.isLock)
    CfUtils.SetActive(self.ImgLock, self.config.isLock)
    --CfUtils.SetActive(self.ImgBg, not self.config.isLock)
    CfUtils.SetActive(self.ImgBgSelect, self.config.isSelected)
    CfUtils.SetActive(self.ImgIconSelect, self.config.isSelected)
    CfUtils.SetActive(self.ImgBgGet, self.config.isGet)
    CfUtils.SetActive(self.ImgNew, self.config.isNew)
    local animName = self.config.isSelected and "ActivityMidFestivalStory_Cell_Select" or "ActivityMidFestivalStory_Cell_Default"
    CfUtils.PlayAnimation(self.controller.gameObject, animName)

    if self.config.isSelected then
        --- 刷新右侧面板信息
        Events.Broadcast(Constants.EventNames.MidFestivalRefreshRightTab, self.questVo, self._purePlot)
    end
end

function ActivityMidFestivalLeftTabCellNode:OnClick()
    if self.config.isLock then
        GameUtils.Toast(localize("通关最新关卡后解锁"))
        return
    end

    if self.cb then
        self.cb()
    end
end

function ActivityMidFestivalLeftTabCellNode:PlaySelectAnim()
    CfUtils.PlayAnimation(self.controller.gameObject, "ActivityMidFestivalStory_Cell_Select")
end
